const { plugin_settings_task_notifier: config, csrfToken } = await chrome.storage.local.get(['plugin_settings_task_notifier', 'csrfToken']);
if (config?.enabled) {
  setInterval(async () => {
    const res = await fetch('https://app.outlier.ai/corp-api/qm/assigned-operation-nodes?fetchMetadata=true&onlyPending=true&page=1&project=&sortOrder=1', {
      headers: { 'X-CSRF-Token': csrfToken }
    });
    const data = await res.json();
    if (data?.nodes?.length > 0) {
      new Audio(config.audioUrl).play().catch(() => {
         new Notification('New Tasks Available!');
      });
    }
  }, config.period * 60000);
}
